def decorator(function):
    return function


@decorator
def outer(a, b=2, /, c=3, *args, d, e=5, **kwargs):
    total = a + b
    def inner(x):
        nonlocal total
        total += x
        return total * c
    squares = [n * n for n in range(10) if n % 2]
    mapping = {k: v for k, v in kwargs.items()}
    unique = {s for s in args}
    lazy = (q for q in args)
    try:
        value = inner(d) // e
    except (ZeroDivisionError, ValueError) as error:
        value = str(error)
    except Exception:
        raise
    else:
        value = -value
    finally:
        total = 0
    with open(os.devnull) as handle, open(os.devnull) as other:
        handle.read()
    while total < 100:
        total += 1
        if total == 50:
            break
        elif total > 1000:
            continue
    for index, item in enumerate(args):
        if (n := len(str(item))) > 3:
            print(f"{index!r:>10} {item} {n:{c}}")
    assert total is not None, "never"
    del squares[0]
    return inner, mapping, unique, lazy, value, lambda y, *, z=1: y + z


class Base:
    attribute: int = 1

    def __init__(self, value):
        self.value = value

    @property
    def doubled(self):
        return self.value * 2

    @staticmethod
    def make():
        return Base(1)


class Child(Base, metaclass=type):
    def __init__(self, value):
        super().__init__(value)
        self.extra = [value] * 3

    async def fetch(self, source):
        async with source as stream:
            async for chunk in stream:
                yield chunk
        await source.close()


def generator():
    received = yield 1
    yield from range(received or 3)


